class Statistics
    private define total as integer;
    private define count as integer;

    method constructor(aTotal as integer, aCount as integer)
        this.total <- aTotal;
        this.count <- aCount;
    endMethod

    public method Average() as real
        return this.total / this.count;
    endMethod
endClass

algorithm ComputeAverage
    dimension numbers[5] as integer;
    define i as integer;
    define total as integer;
    define statistics as Statistics;
    for i <- 0 to 4 step 1 do
        read numbers[i];
    endFor
    total <- 0;
    for i <- 0 to 4 step 1 do
        total <- total + numbers[i];
    endFor
    statistics <- new Statistics(total, 5);
    write statistics.Average();
endAlgorithm
